	private static void assertProbeTiming(long elapsedNanos, long elapsedWallMillis, long expectedChargeNanos)
			throws IOException {
		Fixture fixture = new Fixture(1_000L);
		LmdbNativeStrategyProposal<String> incumbent = proposal(LmdbNativeAttemptMetrics.PATH_BATCH,
				() -> "incumbent");
		LmdbNativeCostEstimate incumbentEstimate = incumbent.adaptiveEstimate(-1D);
		for (int i = 0; i < 30; i++) {
			fixture.model.recordCompleted(incumbentEstimate, incumbentEstimate.total(), 100_000_000L, 1.0,
					fixture.model.currentRegime());
		}
		fixture.store.safetyLedger().earn(1_000_000_000_000L);
		long creditBefore = fixture.store.safetyLedger().availableNanos();
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter
				.<String>forModel(null, -1D, fixture.model)
				.probeHarness(LmdbNativeProbeHarness.blocking())) {
			arbiter.offer(() -> incumbent);
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> {
				fixture.nano.addAndGet(elapsedNanos);
				fixture.wall.addAndGet(elapsedWallMillis);
				return "probe";
			}, LmdbNativeWork.UNKNOWN, LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, () -> {
			}));
			try (LmdbNativeStrategySelection<String> selection = arbiter.selectWithObservation()) {
				assertNotNull(selection);
				assertEquals("probe", selection.value());
				assertEquals(LmdbNativeCostObservation.Role.PROBE, selection.observation().role());
				assertEquals(elapsedNanos, selection.observation().snapshot().totalNanos());
				assertEquals(expectedChargeNanos, creditBefore - fixture.store.safetyLedger().availableNanos());
			}
		}
	}

	private static LmdbNativeStrategyProposal<String> proposal(String tag,
			LmdbNativeStrategyProposal.Opener<String> opener) {
		return new LmdbNativeStrategyProposal<>(opener, 1_000D, tag);
	}

